import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"旋转卡壳","description":"","frontmatter":{"title":"旋转卡壳","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rotating-calipers.md","filePath":"cs/rotating-calipers.md","lastUpdated":1789023840000}'),c={name:"cs/rotating-calipers.md"};function _(m,a,u,f,E,T){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="旋转卡壳" tabindex="-1">旋转卡壳 <a class="header-anchor" href="#旋转卡壳" aria-label="Permalink to &quot;旋转卡壳&quot;">​</a></h1><div class="epigraph"><p>凸包上一对对踵点随边旋转；直径、最小宽度、凸多边形距离在 $O(n)$ 内扫完。</p><footer>—— 据 Toussaint, Solving Geometric Problems with the Rotating Calipers, 1983；CLRS 第 33 章整理</footer></div><p>上一课<a href="/cs/convex-hull">凸包</a>给出凸多边形。直径：最远点对应在凸包上，且常是对踵。缺口是旋转卡壳：卡尺贴一条边，对侧点单调移动。不重写 Graham。后课扫描线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素 \\(O(h^2)\\) 对包上点。卡壳：边 \\(e\\) 的对踵（离直线最远点）随 \\(e\\) 沿边界单调。直径 = 对踵距离最大值。最小面积外接矩形同技巧。两凸包最近/最远点对也可卡。</p><p>缺口是单调对踵，不是旋转几何公式课。</p><h3 id="先凸包" tabindex="-1">先凸包 <a class="header-anchor" href="#先凸包" aria-label="Permalink to &quot;先凸包&quot;">​</a></h3><p>非凸点集必须先凸包。卡壳假定凸。不要在凹多边形上直接转。</p><p><span class="marginnote">Toussaint 1983 综述卡壳。直径也见 Shamos。后课最近点对是分治，对象全体点不是直径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>凸包逆时针。双指针 \\(i,j\\)。边 \\((i,i+1)\\) 时推进 \\(j\\) 直到面积/叉积不再增。记录答案。转一圈 \\(O(h)\\)。</p>',11)),(e(),n(p,null,{default:r(()=>[h(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%87%B8%E5%8C%85%22%5D%20--%3E%20CAL%5B%22%E5%AF%B9%E8%B8%B5%E5%8F%8C%E6%8C%87%E9%92%88%22%5D%0A%20%20CAL%20--%3E%20D%5B%22%E7%9B%B4%E5%BE%84%20%2F%20%E5%AE%BD%E5%BA%A6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>共线边要对齐策略。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>凸使对踵单调，不会来回。与卡尺物理图像一致。与旋转卡壳求矩形：角度在边上变化。与 SMAWK 无关。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写三维直径。带权卡壳不写。后课默认：凸多边形直径 \\(O(n)\\) 卡壳。下一课扫描线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对踵随边单调；直径 \\(O(h)\\)。</li><li>先凸包 \\(O(n\\log n)\\)。</li><li>只对凸多边形。</li><li>出处：Toussaint, 1983。</li></ul>',7))])}const B=o(c,[["render",_]]);export{A as __pageData,B as default};
